const drownedSailorSheet=new Image();drownedSailorSheet.assetSrc='assets/drowned-sailor-v1.png';
function beginDrownedSailor(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy),ux=dx/(len||1),uy=dy/(len||1);if(!len)ux=1;let reach=Math.min(360,Math.max(200,len+70)),origin={x:e.x,y:e.y},end={...origin};for(let s=6;s<reach+6;s+=6){let d=Math.min(s,reach),q={x:e.x+ux*d,y:e.y+uy*d};if(!passable(q.x,q.y,12)||!lineClear(end,q,12))break;end=q;}e.state='attack';e.elapsed=0;e.struck=false;e.facing=dx-dy<0?-1:1;e.attack={pattern:'drownedReturningAnchor',bespoke:true,windup:.9,origin,end,anchor:{...origin},hits:[false,false],crashed:false,crashAt:null};}
function drownedAnchorPoint(a,t){let f=t<.9?0:t<1.35?(t-.9)/.45:t<1.65?1:t<2.3?1-(t-1.65)/.65:0;return{x:a.origin.x+(a.end.x-a.origin.x)*f,y:a.origin.y+(a.end.y-a.origin.y)*f};}
function drownedAnchorContact(point,start,end){let dx=end.x-start.x,dy=end.y-start.y,d2=dx*dx+dy*dy;if(d2<1e-10)return null;let t=Math.max(0,Math.min(1,((point.x-start.x)*dx+(point.y-start.y)*dy)/d2)),q={x:start.x+dx*t,y:start.y+dy*t};return dist(q,point)<=22+1e-8?q:null;}
const drownedSailorAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e2')return drownedSailorAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='drownedReturningAnchor'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginDrownedSailor(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,84*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 for(let [i,startTime,endTime,damage]of [[0,.9,1.35,56],[1,1.65,2.3,68]]){if(a.crashed||before>=endTime||e.elapsed<startTime)continue;let start=drownedAnchorPoint(a,Math.max(before,startTime)),target=drownedAnchorPoint(a,Math.min(e.elapsed,endTime)),dx=target.x-start.x,dy=target.y-start.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6)),end={...start};for(let j=1;j<=n;j++){let q={x:start.x+dx*j/n,y:start.y+dy*j/n};if(!passable(q.x,q.y,12)||!lineClear(end,q,12)){a.crashed=true;a.crashAt=e.elapsed;break;}end=q;}a.anchor=end;let contact=drownedAnchorContact(p,start,end);if(!dead&&!a.hits[i]&&!(p.inv>0)&&contact&&lineClear(a.origin,contact)&&lineClear(contact,p)){a.hits[i]=true;e.struck=true;hurt(damage);}if(before<startTime&&e.elapsed>=startTime)playSound('slash',e.x,e.y);}
 if(a.crashed?e.elapsed>=a.crashAt+1.2:e.elapsed>=2.9){e.attack=null;e.state='idle';e.t=2.7;}
};
const drownedSailorDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e2'||!drownedSailorSheet.complete||!drownedSailorSheet.naturalWidth||!drownedSailorSheet.naturalHeight)return drownedSailorDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='drownedReturningAnchor')f={row:2,col:e.attack.crashed?3:e.elapsed<.9?0:e.elapsed<1.65?1:e.elapsed<2.3?2:3};let q=project(e.x,e.y),sw=drownedSailorSheet.naturalWidth/4,sh=drownedSailorSheet.naturalHeight/3,w=235,h=w*sh/sw,anchor=.96;ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,drownedSailorSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(drownedSailorSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const drownedSailorSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e2'?150:drownedSailorSizeBase(e);
const drownedSailorGroundBase=drawGroundEffects;drawGroundEffects=()=>{drownedSailorGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e2'):enemies)){let a=e.attack;if(e.species!=='r8e2'||e.hp<=0||a?.pattern!=='drownedReturningAnchor'||!visibleAt(e.x,e.y))continue;if(a.crashed||e.elapsed>=2.3){groundRing(e.x,e.y,30,'#9bddcf',2);continue;}let dx=a.end.x-a.origin.x,dy=a.end.y-a.origin.y,len=Math.hypot(dx,dy);if(!len)continue;let nx=-dy/len*22,ny=dx/len*22,points=[{x:a.origin.x+nx,y:a.origin.y+ny},{x:a.end.x+nx,y:a.end.y+ny},{x:a.end.x-nx,y:a.end.y-ny},{x:a.origin.x-nx,y:a.origin.y-ny}];ctx.save();ctx.fillStyle='#98b9bd22';ctx.strokeStyle=e.elapsed>=1.65?'#e2bd86':'#9bc9ce';ctx.lineWidth=1;ctx.beginPath();points.forEach((point,i)=>{let q=project(point.x,point.y);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();groundRing(a.origin.x,a.origin.y,22,'#9bc9ce',1);groundRing(a.end.x,a.end.y,22,'#9bc9ce',1);}};
const drownedSailorEffectsBase=drawEffects;drawEffects=()=>{drownedSailorEffectsBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e2'):enemies)){let a=e.attack;if(e.species!=='r8e2'||e.hp<=0||a?.pattern!=='drownedReturningAnchor'||a.crashed||e.elapsed<.9||e.elapsed>=2.3)continue;let q=project(e.x,e.y),r=project(a.anchor.x,a.anchor.y);if(!visibleAt(a.anchor.x,a.anchor.y)&&!visibleAt(e.x,e.y))continue;ctx.save();ctx.strokeStyle='#b3a489';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y-22);ctx.lineTo(r.x,r.y-12);ctx.stroke();ctx.translate(r.x,r.y-12);ctx.strokeStyle='#d1b995';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(0,11);ctx.moveTo(-9,-7);ctx.lineTo(9,-7);ctx.moveTo(-13,1);ctx.lineTo(-8,10);ctx.lineTo(0,14);ctx.lineTo(8,10);ctx.lineTo(13,1);ctx.stroke();ctx.restore();}};
